pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 0, 1_000);

        vm.deal(caller, amount);

        bool success;
        vm.prank(caller);
        (success, ) = address(c).call{value: amount}(abi.encodeWithSignature("play()"));

        assertTrue(success == (amount == 10));
    }
}
